(* [comment removed for export] *)
Definition toD_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word)
    (lo : Z) (m : word -> option byte) (G f : word) (p s : Z) : machine_state -> Prop :=
  fun ms' => exists (ia iz ir : Z) (ws : list word) (w0 : word) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s3' s5' s7' s8' s9' s10' t3' t4' t5' t6'
                    (F' : bvmap 5 word) fc' m' j1 j2 j3,
    (0 <= ia < iz)%Z /\ (iz <= 128)%Z /\ length ws = 128%nat /\ (ir = 0 \/ ir = 122)%Z /\ (ir = 122 -> ia <= 122)%Z /\
    limbs_ok ws ia (Z.max iz (ir + 1)) /\ (ir = 0%Z -> lowz ws ia) /\
    nth_error ws (Z.to_nat ia) = Some w0 /\ bv_unsigned w0 <> 0%Z /\ (ia = 0%Z -> bv_unsigned w0 < 999999999)%Z /\
    ms' = MS (mkR ra' (Z_to_bv 64 (bv_unsigned sp + -1056)) gp tp t0' t1' t2' sp (Z_to_bv 64 (bv_unsigned sp + -1056 + 4 * ia))
                  a0' a1' a2' a3' a4' a5' a6' a7'
                  (Z_to_bv 64 p) s3' (Z_to_bv 64 103) s5' (Z_to_bv 64 (bv_unsigned sp + -1056 + 4 * ir)) s7' s8' s9' s10'
                  (Z_to_bv 64 (bv_unsigned sp + -1056 + 4 * iz)) t3' t4' t5' t6') F' (Z_to_bv 64 0x141d3c) fc' None m' (seg_rom rsegs)
    /\ (exists c, F' = bvmap_set 10 c F)
    /\ munch [(bv_unsigned sp + -4640, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -1056)
    /\ u32arr rsegs m' (bv_unsigned sp + -1056) ws
    /\ rw_cells rsegs m' (bv_unsigned sp + -544)
         [C8 (Z_to_bv 64 0); CB 40 j1; C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); CB 8 j2; C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0x6b3b40);
          C8 (Z_to_bv 64 (1 - s)); C8 (Z_to_bv 64 (81973 - s)); C8 (Z_to_bv 64 s); C8 f; C4 (Z_to_bv 64 0); CB 308 j3;
          C8 G; C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ ro_cells rsegs m' 0x157b38 [C8 (Z_to_bv 64 0x6b3b40)] /\ ro_cells rsegs m' 0x6b3b40 [C8 G].

Theorem fmtfp_toD_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (d p : Z) (G : word),
  stk rsegs m lo (bv_unsigned sp) -> WAI.senv m lo -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 4640)%Z -> (bv_unsigned sp < 2 ^ 63)%Z ->
  ro_cells rsegs m 0x157b38 [C8 (Z_to_bv 64 0x6b3b40)] -> ro_cells rsegs m 0x6b3b40 [C8 G] -> (0x6b3d78 <= lo)%Z -> (bv_unsigned sp + 64 <= lo + WAI.WIN)%Z ->
  (0 <= d < 2 ^ 64)%Z -> (0 < d mod 2 ^ 63 < 2047 * 2 ^ 52)%Z -> (9 <= p <= 20)%Z ->
  bv_unsigned a1 = lo64 (f128_of_d d) -> bv_unsigned a2 = hi64 (f128_of_d d) ->
  a3 = Z_to_bv 64 1 -> a4 = Z_to_bv 64 p -> a5 = Z_to_bv 64 0 -> a6 = Z_to_bv 64 103 -> a7 = Z_to_bv 64 0 ->
  evt rsegs (toD_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F lo m G a0 p (d / 2 ^ 63))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x141754) fc None m (seg_rom rsegs)).
