    (fa B0 cap k lbf : Z) (ibuf : list byte) (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk) : machine_state -> Prop :=
  fun ms' => exists (bs : list byte) t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' F' fc' m',
      (WDL.gnum (zs bs) = true \/ WDL.gspecial (zs bs)) /\ (1 <= Z.of_nat (length bs) <= 26)%Z /\
      ms' = MS (mkR ora fp gp tp t0' t1' t2' os0 os1 (Z_to_bv 64 (Z.of_nat (length bs))) a1' a2' a3' a4' a5' a6' a7' os2 os3 os4 os5 os6 os7 os8 os9 os10 os11 t3' t4' t5' t6') F'
               (ret_pc ora) fc' None m' (seg_rom rsegs)
      /\ fkeep F F'
      /\ munch [(lo, bv_unsigned fp); (B0 + k, B0 + k + 41); (fa + 40, fa + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned fp)
      /\ fst_at m' fa B0 cap (k + Z.of_nat (length bs)) lbf (upd_bytes ibuf (Z.to_nat k) bs) rpos rend wbase wfn bufp bsz mode lockv cookie J.

Theorem fmtfp_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo d p fa B0 cap k lbf : Z) (G : word) (ibuf : list byte)
   (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk),
  stk rsegs m lo (bv_unsigned sp) -> WAI.senv m lo -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 4640)%Z -> (bv_unsigned sp < 2 ^ 63)%Z ->
  ro_cells rsegs m 0x157b38 [C8 (Z_to_bv 64 0x6b3b40)] -> ro_cells rsegs m 0x6b3b40 [C8 G] -> (0x6b3d78 <= lo)%Z ->
  (0 <= d < 2 ^ 64)%Z -> (d mod 2 ^ 63 <> 0)%Z -> (p = 15 \/ p = 17)%Z ->
  a0 = Z_to_bv 64 fa -> bv_unsigned a1 = lo64 (f128_of_d d) -> bv_unsigned a2 = hi64 (f128_of_d d) ->
  a3 = Z_to_bv 64 1 -> a4 = Z_to_bv 64 p -> a5 = Z_to_bv 64 0 -> a6 = Z_to_bv 64 103 -> a7 = Z_to_bv 64 0 ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> fgeo lo (bv_unsigned sp) fa B0 cap -> (k + 41 <= cap)%Z ->
  evt rsegs (fmtfp_rets ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F lo m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x141754) fc None m (seg_rom rsegs)).
Proof.
